# Project A / storage/index.py
class PageIndex:
    def __init__(self):
        self.pages = {}
        self.version = 0

    def put(self, key, page_id):
        self.pages[key] = page_id
        self.version += 1

    def get(self, key):
        return self.pages.get(key)

    def snapshot(self):
        return self.version, dict(self.pages)
# Project A / storage/transaction.py
class Transaction:
    def __init__(self, index):
        self.index = index
        self.pending = []

    def stage(self, key, page_id):
        self.pending.append((key, page_id))

    def commit(self):
        for key, page_id in self.pending:
            self.index.put(key, page_id)
        self.pending.clear()
# Project A / tests/test_snapshot.py
def test_snapshot_is_stable(index):
    index.put("alpha", 10)
    version, snapshot = index.snapshot()
    index.put("beta", 20)
    assert version == 1
    assert snapshot == {"alpha": 10}
